import{_ as n,C as i,c as s,o as l,aj as h,j as t,G as o,a as d,w as p}from"./chunks/framework.Bfdr4H5E.js";const c="/sk/images/Seller-Bought-Phone.webp",u="/sk/images/Buyer-at-Auction.webp",m="/sk/images/Supply-over-Demand.webp",g="/sk/images/Buyers-Scenario.webp",f="/sk/images/Demand-over-Supply.webp",E=JSON.parse('{"title":"2nd Hand Mobile Auction","description":"","frontmatter":{"outline":"deep","prev":{"text":"PRICE","link":"/trading-with-pav/price"},"next":{"text":"Types of Orders","link":"/trading-with-pav/types-of-orders"}},"headers":[],"relativePath":"trading-with-pav/2nd-hand-mobile-auction.md","filePath":"trading-with-pav/2nd-hand-mobile-auction.md"}'),y={name:"trading-with-pav/2nd-hand-mobile-auction.md"};function b(w,e,v,k,B,A){const a=i("GraphComment"),r=i("ClientOnly");return l(),s("div",null,[e[0]||(e[0]=h('<h1 id="_2nd-hand-mobile-auction" tabindex="-1">2nd Hand Mobile Auction <a class="header-anchor" href="#_2nd-hand-mobile-auction" aria-label="Permalink to &quot;2nd Hand Mobile Auction&quot;">​</a></h1><p>In this article we are going to explore a simplified version of a 2nd Hand Mobile Auction to see how the supply demand move the price.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#the-seller">The Seller</a></li><li><a href="#the-auctioneer">The Auctioneer</a></li><li><a href="#the-buyer">The Buyer</a></li><li><a href="#price-discovery">Price Discovery</a><ul><li><a href="#the-negotiation">The Negotiation</a></li><li><a href="#the-agreement">The Agreement</a></li></ul></li><li><a href="#demand-has-overwhelmed-supply">Demand Has Overwhelmed Supply</a></li><li><a href="#supply-has-overwhelmed-demand">Supply Has Overwhelmed Demand</a></li><li><a href="#video">Video</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><h2 id="the-seller" tabindex="-1">The Seller <a class="header-anchor" href="#the-seller" aria-label="Permalink to &quot;The Seller&quot;">​</a></h2><p>Lets say there was a seller who bought a MI Phone for ₹ 15,000/- in a flash sale of 15 min period. As you know that a phone which is sold in flash sale means that phone is in high demand.</p><p>This seems the reason for this seller who bought this phone to make profit from hungry buyers who want this phone badly. The seller didn’t even open the phone in the hopes to get a premium price.</p><p><img src="'+c+'" alt="Seller-Bought-Phone"></p><h2 id="the-auctioneer" tabindex="-1">The Auctioneer <a class="header-anchor" href="#the-auctioneer" aria-label="Permalink to &quot;The Auctioneer&quot;">​</a></h2><p>Now the seller goes to mobile shop to get buyers. Lets call this mobile shop as Auctioneer. Auctioneer will have some commission to sell the phone to potential buyers. The seller tells the situation and lists the price of the phone as ₹ 16,000/-. This is ₹ 1000/- Profit.</p><p>Now the Auctioneer lists this Unopened Brand New Phone for ₹ 16,000/-. After hungry buyers get a wind of this phone they visit the shop with their pricings.</p><p><img src="'+u+'" alt="Buyer-at-Auction"></p><h2 id="the-buyer" tabindex="-1">The Buyer <a class="header-anchor" href="#the-buyer" aria-label="Permalink to &quot;The Buyer&quot;">​</a></h2><p>As you can see in the above image there are 3 Buyers each one with different pricings. Why is that let me elaborate.</p><ol><li>Buyer 1 = ₹ 15,000/-</li><li>Buyer 2 = ₹ 15,500/-</li><li>Buyer 3 = ₹ 16,000/-</li></ol><p>Buyer 1 listed for 15,000 thinking that MRP is final price as its company final price no more than that. As we all know this is true because you can’t go above MRP as its not the fair price its overpriced. As his point of view came to this conclusion.</p><p>Buyer 2 listed for ₹ 15,500/-. Why did the Buyer 2 go beyond the MRP but not with listed price of ₹ 16,000/- by the Seller doesn’t he think that its overpriced. Of course Buyer 2 knows its overpriced but he’s gone till ₹ 15,500/- and not till the Sellers price as he’s desperate to get the phone but not that much right now.</p><p>Buyer 3 listed for ₹ 16,000/-. He knows the Seller’s price is overpriced but he is desperate buyer he’s wants the phone as soon as possible.</p><p>A Few Possible Reasons Why Buyer 3 Might Make This Decision:</p><ol><li>Urgency: The buyer 3 may have an urgent need for the phone, such as replacing a broken device or fulfilling a professional requirement. In such cases, the buyer might be willing to pay a higher price to meet their immediate needs.</li><li>Limited alternatives: The buyer may have exhausted other options and found that this particular seller is the only one offering the phone at the moment. If other sellers are not available or cannot provide the phone within the desired timeframe, the buyer may feel compelled to accept the overpriced offer.</li><li>Convenience: The buyer might prioritize convenience and time savings over getting the best deal. They may not want to spend additional time and effort searching for a better-priced phone or waiting for a lower-priced offer to become available. In this case, the buyer may choose to pay more for the sake of convenience.</li><li>Lack of negotiation skills: The buyer might not feel confident in their ability to negotiate a lower price or may not have the time or inclination to engage in bargaining. As a result, they might accept the overpriced offer rather than risk losing the opportunity altogether.</li></ol><p>It’s important to note that while these reasons might justify the buyer’s decision from their perspective, it’s generally advisable to compare prices, explore other options, and consider the value for money before making a purchase, especially if the price is significantly higher than the market average.</p><p>For the demonstration purpose we gonna keep it till 3 buyers. So as we can see all the buyers listing price to buy has arrived to the Auctioneer. Now to the next process.</p><h2 id="price-discovery" tabindex="-1">Price Discovery <a class="header-anchor" href="#price-discovery" aria-label="Permalink to &quot;Price Discovery&quot;">​</a></h2><p>Before we go further in our Mobile Auction in Local Market lets understand what is price discovery.</p><p>Price discovery is different from valuation. In the above Mobile auction example the MRP of 15,000 is valuation. Price discovery process involves buyers and sellers arriving at a transaction price for a specific item at a given time. It involves the following:</p><ol><li id="my-anchor">Buyers and seller (number, size, location, and valuation perceptions)</li><li>Market mechanism (bidding and settlement processes, liquidity)</li><li>Available information (amount, timeliness, significance and reliability) including futures and other related markets</li><li>Risk management choices.</li><li>“Market” is a broad term that covers buyers, sellers and even sentiment. A single market will have one or more execution venues, which describes where trades are executed. This could be in the street for a street market, or increasingly it could be an electronic or “virtual” venue. Examples of electronic execution venues include NSE Exchange, The London Metal Exchange, NYSE, London Stock Exchanges.</li></ol><p>Price discovery is a summation of the total market’s sentiment at a point in time: a multifaceted, aggregate view on the future. It is how every price in every market is determined.</p><p>The market price is important as it is a factor in the pricing at off market execution venues and direct and indirect derived products. For example, the price of oil has a direct bearing on the cost of tomatoes in cold climates.</p><p>In a dynamic market, the price discovery takes place continuously while items are bought and sold. The price will sometimes fall below the duration average and sometimes exceed the average as a result of the noise due to uncertainties, and transient changes in supply caused by the act of buying and selling: trading.</p><p>A closed market has no price discovery; the last trade price is all that is known. It is common in some markets not to use the actual last traded price but some sort of average / weighted mean. This is to prevent price manipulation by the execution of outliers on or at market close.</p><h3 id="the-negotiation" tabindex="-1">The Negotiation <a class="header-anchor" href="#the-negotiation" aria-label="Permalink to &quot;The Negotiation&quot;">​</a></h3><p>Now that we know what price discovery is lets get into our mobile auction. Here the Auctioneer has offer of ₹ 16,000/- and matching bid from Buyer 3 for ₹ 16,000/-.<br> Will the mobile get sold for ₹ 16,000/- to Buyer 3 ? No now the Auctioneer will start the negotiation process (Price Discovery at work). Lets see where this goes.</p><p>Auctioneer will contact the Buyer 1 and tell the current situation of price. The buyer 1 tell that he is not interested at this offer price and quits. Now there are 2 Buyers remaining.</p><p>Auctioneer now contact the Buyer 2 and tell the current situation of price. The Buyer 2 tells that he is increasing the bid to ₹ 16,100/- The Buyer 2 might have increase the bid due to one of these circumstance <a href="/sk/trading-with-pav/2nd-hand-mobile-auction.html#price-discovery">discussed above</a>.</p><p>Now Auctioneer relays this to Buyer 3, hearing this he increase his bid to ₹ 16,500/- again Auctioneer goes to Buyer 2 and updates him. Buyer 2 updates his bid to ₹ 16,600/-</p><p>Again Buyer 3 updates his bid to ₹ 17,000/- and Auctioneer goes to Buyer 2 and updates him and Buyer 2 looking at the current offer is not interested and quits.</p><h3 id="the-agreement" tabindex="-1">The Agreement <a class="header-anchor" href="#the-agreement" aria-label="Permalink to &quot;The Agreement&quot;">​</a></h3><p>As there is no buyer to compete the Auctioneer sells to the Buyer 3 for ₹ 17,000/- a whooping ₹ 2,000 profit. In short Seller’s plan worked made profit and the Buyer 3 also got the product cause he agreed for that price although he got for the highest price in market context he made loss.</p><p><img src="'+m+'" alt="Supply-over-Demand"></p><h2 id="demand-has-overwhelmed-supply" tabindex="-1">Demand Has Overwhelmed Supply <a class="header-anchor" href="#demand-has-overwhelmed-supply" aria-label="Permalink to &quot;Demand Has Overwhelmed Supply&quot;">​</a></h2><p>In the above example,</p><ul><li><strong>Demand</strong> consisted of multiple buyers <strong>all wanting to buy and willing to pay higher prices to do so</strong>.</li><li><strong>Supply</strong> consisted of a single seller, <strong>willing to allow price to increase</strong> until there are no more buyers.</li><li><strong>Demand</strong> has overwhelmed <strong>Supply</strong>, leading to price rallying.</li><li><strong>Price</strong> continued to rally <strong>until</strong> there were no more <strong>buyers</strong> willing to pay a <strong>higher price</strong>.</li></ul><p>Now lets look the same scenario with different condition i.e. when buyer’s win.</p><h2 id="supply-has-overwhelmed-demand" tabindex="-1">Supply Has Overwhelmed Demand <a class="header-anchor" href="#supply-has-overwhelmed-demand" aria-label="Permalink to &quot;Supply Has Overwhelmed Demand&quot;">​</a></h2><p><img src="'+g+`" alt="Buyers-Scenario"></p><p>Now in the above image you can see same condition as above i.e. Sellers wants to profit like the last time. Auctioneer has listed offer price of ₹ 16,000/- and the all the 3 buyers biding is as follows:</p><ol><li>Buyer 1 – ₹ 15,500</li><li>Buyer 2 – ₹ 15,000</li><li>Buyer 3 – ₹ 15,800</li></ol><p>As you can see none of the above bid is matching the current offer which means these buyers are tough crowd but seller still has time to wait for new buyers because its a brand new unopened mobile piece with high demand.</p><p>Lets bring in a new Twist in this Market. There is Breaking news about this Mobile floating around.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark has-diff has-focused-lines vp-code" tabindex="0"><code><span class="line has-focus"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Breaking News  </span></span>
<span class="line highlighted diff add"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Battery Exploded </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">of</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Brand New </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Phones </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">of</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Model No </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">XA921</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">That Were on Recent Flash Sale. </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Manufacturer Has Press Released Saying That Company Is Looking Into It.</span></span>
<span class="line highlighted diff remove"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Further Flash Sale Are Canceled Until Final Verdict. </span></span></code></pre></div><p>Now the seller has got the wind of the news now he has no time to wait it out he tell The Auctioneer to sell to highest Bidder before all the buyers get wind of these news. He can still make profit form Buyer 3 (800 profit) or Buyer 1 (500 profit) or Buyer 2 (0 MRP Breakeven).</p><p>Sadly the news was already hit to the buyers and following offer bid round 1 takes place</p><ol><li>Auctioneer lowers the offer from ₹ 16,000 to Buyer 3’s bid ₹ 15,800 but Buyer 3 lowers the bid to ₹ 14,800 a whooping ₹ 1,000 less.</li><li>Auctioneer lowers the offer from ₹ 15,800 to Buyer 1’s bid ₹ 15,500 but Buyer 3 lowers the bid to ₹ 14,500 a whooping ₹ 1,000 less.</li><li>Auctioneer lowers the offer from ₹ 15,500 to Buyer 2’s bid ₹ 15,000 but Buyer 3 lowers the bid to ₹ 13,500 a whooping ₹ 1,500 less.</li></ol><p>Now you have seen how the news change the direction of power from Seller to Buyer and the round 2 takes place and the seller wanna get out of this situation cuz the value dropped from breakeven i.e. MRP price of ₹ 15,000. Now we have to see how low seller goes to quit.</p><ol><li>Auctioneer lowers the offer from ₹ 15,000 to Buyer 3’s bid ₹ 14,800 but Buyer 3 lowers the bid to ₹ 13,000 a whooping ₹ 1,800 less.</li><li>Auctioneer lowers the offer from ₹ 14,800 to Buyer 1’s bid ₹ 14,500 but Buyer 1 lowers the bid to ₹ 11,000 a whooping ₹ 3,500 less.</li><li>Auctioneer lowers the offer from ₹ 14,500 to Buyer 2’s bid ₹ 13,500 but Buyer 2 lowers the bid to ₹ 11,500 a whooping ₹ 2,000 less.</li></ol><p>As you can see value is going down like a rocket. The seller’s now no longer affords loss and wants to get out so he tells The Auctioneer to match the highest bid without lowering the price any further. So then start round 3</p><ol><li>Auctioneer lowers the offer from ₹ 13,500 to Buyer 3’s bid ₹ 13,000 but Buyer 3 lowers the bid to ₹ 12,000. The Auctioneer accepts this bid (As the new bid was greater then Buyer 1 and 2 and this information was unknow to Buyer 3 he accepts the ₹ 12,000 offer because he thought he won the deal) and the phone is sold to Buyer 3.</li></ol><p><img src="`+f+'" alt="Demand-over-Supply"></p><p>In the above example, despite only one seller, the desperation of that seller has been greater than the desperation of the buyers, resulting in price falling.</p><p>In this case,</p><ul><li><strong>Demand</strong> consisted of multiple buyers <strong>all holding out, the seller would take turns lowering the asking(offer) price</strong>.</li><li><strong>Supply</strong> consisted of a single seller, <strong>allowing for price to decrease</strong> until it reached a point at which he was not willing to get any lower.</li><li><strong>Supply</strong> has overwhelmed <strong>Demand</strong>.</li><li><strong>Price</strong> has fallen <strong>until</strong> no-seller willing to sell at a <strong>lower price</strong>.</li></ul><p>Hope you understood The Auction process of a local market which was Forward auction, next we are going to see the same process in stock market which happens electronically but slightly different Auction which is called The Dual Auction.</p><p>But before we dive into it we going to get to Types of Orders.</p><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2>',63)),e[1]||(e[1]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/kE_RtPK6bwY",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[2]||(e[2]=t("p",null,"The above video explains this article in hindi language.",-1)),e[3]||(e[3]=t("h2",{id:"comments",tabindex:"-1"},[d("Comments "),t("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),o(r,null,{default:p(()=>[o(a)]),_:1})])}const x=n(y,[["render",b]]);export{E as __pageData,x as default};
